{
        GF_TrackBox *trak;
        trak = gf_isom_get_track_from_file(movie, trackNumber);
        if (!trak) return 0;

#ifndef GPAC_DISABLE_ISOM_WRITE
        /*in all modes except dump recompute duration in case headers are wrong*/
